// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-nav-bar.js';
import './md-gb-nav-bar-item.js';
import '../../../behaviors/element-internals.js';
import {internals} from '../../../behaviors/element-internals.js';
import '../../styles/adopt-styles.js';
import {adoptStyles} from '../../styles/adopt-styles.js';
import {styles as m3Styles} from '../../styles/m3.cssresult.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: {items: HTMLElement[]}, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}


adoptStyles(document, [m3Styles]);

const SELECTION_LABELS = ["Alpha","Bravo","Charlie","Delta"];
const SELECTION_MODE_ATTRS: {[mode: string]: string} = {"single":""};

interface SelectionFixture {
  form: HTMLFormElement;
  group: HTMLElement;
  items: HTMLElement[];
}

async function setupSelection(opts: {
  mode: string;
  required?: boolean;
  disabled?: number;
  name?: boolean;
}): Promise<SelectionFixture> {
  const root = await mount(html``);
  const attrs = [
    SELECTION_MODE_ATTRS[opts.mode],
    opts.required ? '' : '',
    opts.name ? 'name=""' : '',
  ]
    .filter(Boolean)
    .map((attr) => ' ' + attr)
    .join('');
  const item = (label: string, extra: string) => `<md-gb-nav-bar-item${extra}>${label}</md-gb-nav-bar-item>`;
  const items = SELECTION_LABELS.map((label, i) => item(label, opts.disabled === i ? ' disabled' : '')).join('');
  root.innerHTML = `<form><md-gb-nav-bar aria-label="Main"${attrs}>${items}</md-gb-nav-bar></form>`;
  await settle();
  const f = {
    form: root.querySelector('form')!,
    group: root.querySelector<HTMLElement>('md-gb-nav-bar')!,
    items: [...root.querySelectorAll<HTMLElement>('md-gb-nav-bar-item')],
  };
  await settle();
  return f;
}

/** The labels of the selected items, in order. */
function selectedLabels(f: SelectionFixture) {
  return f.items.filter((item) => (item as HTMLElement & {selected: boolean}).selected).map((item) => item.textContent!.trim());
}

/** The ARIA state of each item. */
function ariaStates(f: SelectionFixture) {
  return f.items.map((item) => (item as unknown as Record<symbol, Record<string, string | null>>)[internals]['ariaSelected']);
}

/** The event types the group dispatches, in order. */
function recordSelectionEvents(group: HTMLElement) {
  const log: string[] = [];
  for (const type of ['input', 'change']) group.addEventListener(type, () => log.push(type));
  return log;
}


describe('<md-gb-nav-bar> selection contract (SelectionController: single, always one selected)', () => {
  afterEach(() => container?.remove());

  it('selects the clicked item and unselects the previous one (single-select)', async () => {
    // spec: navigation-bar-0d46a4
    const f = await setupSelection({mode: 'single'});
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[2].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('selects the focused item with Space and with Enter', async () => {
    // spec: navigation-bar-0d46a4, navigation-bar-5077b0
    const f = await setupSelection({mode: 'single'});
    await focusItem(f, 1);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 2);
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('starts with the first item selected', async () => {
    const f = await setupSelection({mode: 'single'});
    expect(selectedLabels(f)).toEqual(['Alpha']);
  });

  it('keeps the selected item selected when it is clicked or activated again, but still switches', async () => {
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 1);
    await press('Space');
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[3].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Delta']);
  });

  it('reflects the selection as aria-selected (ElementInternals) on each item', async () => {
    const f = await setupSelection({mode: 'single'});
    expect(ariaStates(f)).toEqual(['true', 'false', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'true', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'true', 'false', 'false']);
  });

  it('fires change on the group when the user selects, by click and by key', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual(['change']);
    log.length = 0;
    await focusItem(f, 2);
    await press('Space');
    expect(log).toEqual(['change']);
  });

  it('fires no events when the selection is changed programmatically', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    (f.items[2] as HTMLElement & {selected: boolean}).selected = true;
    await settle();
    expect(selectedLabels(f)).toContain('Charlie');
    expect(log).toEqual([]);
  });

  it('fires no events when nothing changes (the selected item of a required group)', async () => {
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual([]);
  });

  it('does not select a disabled item', async () => {
    const f = await setupSelection({mode: 'single', disabled: 1});
    const before = selectedLabels(f);
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(before);
    expect(log).toEqual([]);
  });
});
